import type { JobResult } from "@/server/jobs/types";

/** Organizations recounted per pass; the list is oldest-measured first. */
const ORG_BATCH = 25;

const logger = createLogger("usage-rollup-job");

/**
 * The correction pass for the incremental deltas `UsageService` applies on the
 * write path. Those deltas are cheap but drift — an aborted transaction, a
 * cascade that archived more rows than the event reported — and a quota check
 * is only as trustworthy as the counter behind it.
 */
export async function runUsageRollupJob(now: Date): Promise<JobResult> {
  return runJob("usage-rollup", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      try {
        const usage = await recomputeUsage(orgId);
        result.processed += 1;

        logger.debug("usage recomputed", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
          issues: usage.issuesUsed,
          at: now.toISOString(),
        });
      } catch (error) {
        result.failed += 1;
        logger.error("usage rollup failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Downgrades organizations whose trial ended and emits `billing.plan_changed`.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Where an expired trial lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("trial-expiry-job");

/**
 * Moves expired trials down to the free plan and announces the change so the
 * audit log and any webhook subscriber see it.
 *
 * A tenant that outgrew the free limits during the trial is left alone and
 * logged instead: silently downgrading them would put their workspace over
 * quota, and every subsequent write would fail with no explanation.
 */
export async function runTrialExpiryJob(now: Date): Promise<JobResult> {
  return runJob("trial-expiry", async (result) => {
    const stamp = toIsoTimestamp(now);
    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
    const freeLimits = getPlanLimits(FALLBACK_PLAN);

    for (const subscription of expiring) {
      const orgId = subscription.orgId as OrgId;
      const usage = await usageRepo.getUsage(orgId);

      if (
        usage.seatsUsed > freeLimits.seats ||
        usage.projectsUsed > freeLimits.projects
      ) {
        result.failed += 1;
        logger.warn("trial expired but tenant is over the free plan", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
        });
        continue;
      }

      await subscriptionRepo.updateSubscriptionPlan(
        orgId,
        FALLBACK_PLAN,
        subscription.interval,
      );

      await emit("billing.plan_changed", {
        orgId,
        actorId: null,
        occurredAt: stamp,
        from: subscription.plan,
        to: FALLBACK_PLAN,
      });

      result.processed += 1;
    }
  });
}
import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}

